# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM YÖNETİM ANLAYIŞININ GAYESİ: EMANET VE LİYAKAT</text>\n  <!-- Sol Kutu: Erdemli Toplum -->\n  <rect x="25" y="42" width="310" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">YÖNETİMİN GAYESİ: ERDEMLİ TOPLUM</text>\n  <rect x="42" y="78" width="276" height="46" rx="6" fill="#dbeafe" stroke="#3b82f6"/>\n  <text x="180" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">Fârâbî - el-Medînetü\'l-Fâzıla</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#1d4ed8">İyilik ve mutluluk için yardımlaşan toplum</text>\n  <text x="42" y="145" font-size="11.5" fill="#1e3a8a">• Kamu malı ve makamları mülk değil, emanettir.</text>\n  <text x="42" y="167" font-size="11.5" fill="#1e3a8a">• Hz. Ebû Bekir: "Yanlış yaparsam doğrultunuz."</text>\n  <text x="42" y="189" font-size="11.5" fill="#1e3a8a">• Yöneticileri denetlemek halkın sorumluluğudur.</text>\n  <text x="42" y="211" font-size="11.5" font-weight="bold" fill="#1d4ed8">• "Cihadın en üstünü hakkı söylemektir."</text>\n  <!-- Sag Kutu: Nisâ 58 - Emanet ve Liyakat -->\n  <rect x="355" y="42" width="320" height="202" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">EMANET VE LİYAKAT (NİSÂ SURESİ, 58)</text>\n  <rect x="372" y="78" width="286" height="46" rx="6" fill="#fde68a" stroke="#f59e0b"/>\n  <text x="515" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">"Emanetleri mutlaka ehline veriniz..."</text>\n  <text x="515" y="114" text-anchor="middle" font-size="11" fill="#92400e">Görevlendirmede bilgi, ahlak ve yeterlilik</text>\n  <text x="372" y="145" font-size="11.5" fill="#78350f">• Liyakat (Ehliyet): İşi layık olana tevdi etmek.</text>\n  <text x="372" y="167" font-size="11.5" fill="#78350f">• Kayırmacılıktan (iltimas) uzak durmak.</text>\n  <text x="372" y="189" font-size="11.5" fill="#78350f">• Ebû Zer el-Gıfârî örneği: Yöneticilik bir</text>\n  <text x="382" y="206" font-size="11.5" fill="#78350f">üstünlük değil, ağır bir sorumluluk ve emanettir.</text>\n  <text x="515" y="230" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">İşi ehline vermemek emanete aykırı davranmaktır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM MEDENİYETİNDE ADALET ANLAYIŞI VE UYGULAMALARI</text>\n  <!-- Sol: Kur\'an\'da Adalet İlkeleri -->\n  <rect x="25" y="42" width="315" height="202" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">KUR\'AN VE SÜNNETTE ADALET ÖLÇÜSÜ</text>\n  <rect x="42" y="78" width="280" height="52" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="182" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">Nisâ Suresi, 135 &amp; Mâide Suresi, 8</text>\n  <text x="182" y="113" text-anchor="middle" font-size="11" fill="#166534">Akraba aleyhine veya düşman lehine dahi</text>\n  <text x="182" y="126" text-anchor="middle" font-size="11" fill="#166534">olsa tarafsızlığı ve hakkaniyeti korumak</text>\n  <text x="42" y="152" font-size="11.5" fill="#14532d">• Kanun önünde herkesin eşit tutulması.</text>\n  <text x="42" y="174" font-size="11.5" fill="#14532d">• Zengin-fakir, güçlü-zayıf ayrımı yapılmaması.</text>\n  <text x="42" y="196" font-size="11.5" fill="#14532d">• Kamu imkanlarının adil şekilde dağıtılması.</text>\n  <text x="42" y="218" font-size="11.5" font-weight="bold" fill="#15803d">• "Adalet mülkün (devlet düzeninin) temelidir."</text>\n  <!-- Sag: Tarihi Uygulamalar -->\n  <rect x="360" y="42" width="315" height="202" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">DEVLET GELENEĞİNDE ADALET KURUMLARI</text>\n  <rect x="378" y="80" width="280" height="45" rx="6" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="518" y="98" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">Kutadgu Bilig (Yusuf Has Hâcib)</text>\n  <text x="518" y="115" text-anchor="middle" font-size="11" fill="#6b21a8">Hükümdar (Kün Togdı) = Adalet ve Doğru Töre</text>\n  <rect x="378" y="135" width="280" height="45" rx="6" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="518" y="153" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">Dîvân-ı Mezâlim ve Adaletnameler</text>\n  <text x="518" y="170" text-anchor="middle" font-size="11" fill="#6b21a8">Yöneticilerin haksızlıklarını denetleyen üst mahkeme</text>\n  <text x="518" y="205" text-anchor="middle" font-size="11.5" fill="#581c87">Beyin ve devletin bekası adil kanunlara,</text>\n  <text x="518" y="222" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7e22ce">zulmün önlenmesine ve yargı bağımsızlığına bağlıdır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM YÖNETİMİNİN BEŞ ESASI: İSTİŞARE VE MEŞRUİYET</text>\n  <!-- Sol: İstişare -->\n  <rect x="25" y="42" width="315" height="202" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">4. İSTİŞARE / ŞÛRA (ORTAK AKIL)</text>\n  <rect x="42" y="78" width="280" height="42" rx="6" fill="#ffedd5" stroke="#f97316"/>\n  <text x="182" y="95" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7c2d12">Âl-i İmrân, 159 &amp; Şûrâ, 38</text>\n  <text x="182" y="111" text-anchor="middle" font-size="11" fill="#9a3412">"Onların işleri aralarında danışma iledir."</text>\n  <text x="42" y="142" font-size="11.5" fill="#7c2d12">• Bedir Savaşı: Ordunun kuyulara göre konumu.</text>\n  <text x="42" y="164" font-size="11.5" fill="#7c2d12">• Uhud Savaşı: Meydan savaşı kararı alınması.</text>\n  <text x="42" y="186" font-size="11.5" fill="#7c2d12">• Hendek Savaşı: Selmân-ı Fârisî\'nin hendek fikri.</text>\n  <text x="42" y="212" font-size="11.5" font-weight="bold" fill="#c2410c">• Ortak akıl hata payını azaltır, bağlılığı artırır.</text>\n  <!-- Sag: Meşruiyet -->\n  <rect x="360" y="42" width="315" height="202" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">5. MEŞRUİYET (HUKUKA UYGUNLUK)</text>\n  <rect x="378" y="78" width="280" height="42" rx="6" fill="#fee2e2" stroke="#ef4444"/>\n  <text x="518" y="95" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7f1d1d">Nisâ Suresi, 59 (Ülü\'l-Emre İtaat)</text>\n  <text x="518" y="111" text-anchor="middle" font-size="11" fill="#991b1b">Yönetimin Kur\'an, sünnet ve hukuka uygunluğu</text>\n  <text x="378" y="142" font-size="11.5" fill="#7f1d1d">• Yönetici de yönetilenler gibi hukuka tabidir.</text>\n  <text x="378" y="164" font-size="11.5" fill="#7f1d1d">• "Allah\'a isyan (günah) konusunda itaat yoktur."</text>\n  <text x="378" y="186" font-size="11.5" fill="#7f1d1d">• "İtaat ancak maruftadır (iyi ve meşru olandadır)."</text>\n  <text x="378" y="212" font-size="11.5" font-weight="bold" fill="#b91c1c">• Hukukun üstünlüğü keyfî yönetimi engeller.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
